#!/usr/bin/env node
/**
 * Build guard for Cloudflare Workers: Next.js Cache Components (`cacheComponents`) and `partialPrefetching` must stay OFF.
 *
 * Why: OpenNext lists Cache Components as "not fully supported" on Cloudflare Workers, and in this app they broke the deployed storefront (reproduced in workerd,
 * docs/cloudflare-deployment.md, section 6): a prerendered page whose cache entry passed its `expire` had to be regenerated by the server at runtime, the regeneration never completed
 * ("The Workers runtime canceled this request because it detected that your Worker's code had hung") and every request for the page answered HTTP 500 until the next deployment; and the partial-
 * prerender resume path left the home page's Suspense boundaries unfinished (React error #419 in the browser). The classic App Router model (ISR + the data cache) works and is what OpenNext supports.
 *
 * Reads the config Next.js recorded in the build output. Usage: node scripts/check-no-cache-components.mjs [path/to/required-server-files.json]   (default .next/required-server-files.json; exit 1 when enabled)
 */
import fs from "node:fs";

/** The settings that must be off, found in a `required-server-files.json` document. */
export function enabledCacheComponentsSettings(doc) {
  const c = doc?.config ?? {};
  const found = [];
  if (c.cacheComponents === true || c.experimental?.cacheComponents === true) found.push("cacheComponents");
  if (c.partialPrefetching === true || c.experimental?.partialPrefetching === true) found.push("partialPrefetching");
  return found;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const file = process.argv[2] ?? ".next/required-server-files.json";
  if (!fs.existsSync(file)) { console.error(`check-no-cache-components: ${file} not found (run the Next.js build first)`); process.exit(2); }
  const found = enabledCacheComponentsSettings(JSON.parse(fs.readFileSync(file, "utf8")));
  if (found.length) {
    console.error(`check-no-cache-components: ${found.join(", ")} enabled in the build. This breaks the storefront on Cloudflare Workers (OpenNext does not fully support Cache Components): see docs/cloudflare-deployment.md, section 6.`);
    process.exit(1);
  }
  console.log(`check-no-cache-components: OK, Cache Components are off (${file})`);
}
